<?php
$worker=static function(array $data):array{$proc=proc_open([PHP_BINARY,__DIR__.'/m10-worker.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['file','/dev/null','a']],$pipes,dirname(__DIR__));m10check(is_resource($proc),'Worker unavailable');fwrite($pipes[0],json_encode($data,JSON_THROW_ON_ERROR)."\n");fflush($pipes[0]);stream_set_timeout($pipes[1],15);m10check(trim((string)fgets($pipes[1]))==='READY','Worker not ready');return [$proc,$pipes];};
$collect=static function(array $w):string{$out=trim((string)fgets($w[1][1]));foreach($w[1]as $pipe)if(is_resource($pipe))fclose($pipe);proc_close($w[0]);return $out;};
$race=static function(array $a,array $b,bool $one=true)use($worker,$collect):array{$x=$worker($a);$y=$worker($b);foreach([$x,$y]as $w){fwrite($w[1][0],"GO\n");fflush($w[1][0]);}$out=[$collect($x),$collect($y)];m10check(count(array_filter($out,fn($r)=>$r==='OK'))===($one?1:2),'Race outcomes: '.implode(',',$out));return $out;};
$job=function(int $id,string $action,?string $qty=null)use($repo,$f,$key):array{$d=$repo->find($id);$i=$repo->items($id)[0];return ['id'=>$id,'version'=>(int)$d['lock_version'],'action'=>$action,'quantities'=>$qty===null?[]:[(int)$i['id']=>$qty],'actor'=>$f['actor'],'key'=>$key()];};
$cv=$quote('8');$cid=$make($cv,'4');$race($job($cid,'edit','3'),$job($cid,'edit','4'));$race($job($cid,'prepare'),$job($cid,'prepare'));$act($cid,'assign');$before=(int)$p->query("SELECT COUNT(*) FROM inventory_movements WHERE source_type='delivery_event'")->fetchColumn();$race($job($cid,'dispatch'),$job($cid,'dispatch'));m10check((int)$p->query("SELECT COUNT(*) FROM inventory_movements WHERE source_type='delivery_event'")->fetchColumn()===$before+1,'Double dispatch moved twice');$qty=$repo->items($cid)[0]['quantity'];$race($job($cid,'confirm',$qty),$job($cid,'confirm',$qty));
// Two HTTP-style retries with the same idempotency key both return the single physical event.
$replay=$make($cv,'1');$act($replay,'prepare');$act($replay,'assign');$data=$job($replay,'dispatch');$before=(int)$p->query('SELECT COUNT(*) FROM delivery_events')->fetchColumn();$race($data,$data,false);m10check((int)$p->query('SELECT COUNT(*) FROM delivery_events')->fetchColumn()===$before+1,'Replay made two events');
// Concurrent cancellation versus physical dispatch cannot both transition the same document.
$cancelRace=$make($cv,'1');$act($cancelRace,'prepare');$act($cancelRace,'assign');$race($job($cancelRace,'dispatch'),$job($cancelRace,'cancel'));
// Independent creations compete for the same remaining documented quantity.
$acv=$quote('1');$qi=$repo->quoteItems($acv)[0];$a=['mode'=>'create','input'=>$input($acv),'quantities'=>[(int)$qi['id']=>'1'],'actor'=>$f['actor']];$b=$a;$b['input']['operation_key']=$key();$race($a,$b);
// A real row lock produces a worker timeout and leaves no partial event or inventory update.
$timeout=$make($cv,'1');$w=$worker($job($timeout,'prepare'));$before=$p->query('SELECT * FROM inventory_balances ORDER BY id')->fetchAll();$p->beginTransaction();$p->query('SELECT id FROM quotes WHERE id='.(int)$repo->find($timeout)['quote_id'].' FOR UPDATE')->fetch();fwrite($w[1][0],"GO\n");fflush($w[1][0]);$out=$collect($w);$p->rollBack();m10check(str_starts_with($out,'REJECT:')&&$before===$p->query('SELECT * FROM inventory_balances ORDER BY id')->fetchAll()&&$repo->find($timeout)['status']==='pending','Timeout leaked changes');
// Different deliveries consume disjoint portions of one reservation at the same time.
$dv=$quote('2');$d1=$make($dv,'1');$d2=$make($dv,'1');foreach([$d1,$d2]as $d){$act($d,'prepare');$act($d,'assign');}$race($job($d1,'dispatch'),$job($d2,'dispatch'),false);
// M09 may reserve only available units while M10 consumes its own M08 commitment.
$mv=$quote('1');$md=$make($mv,'1');$act($md,'prepare');$act($md,'assign');$mt=$ts->create(['source_branch_id'=>$f['branch'],'destination_branch_id'=>$f['other'],'reason'=>'Convivencia M09 concurrente','operation_key'=>$key()],[['variant_id'=>$f['variant'],'unit_id'=>$f['unit'],'quantity'=>'1']],null,$f['actor']);$ti=$tr->items($mt)[0];$race($job($md,'dispatch'),['mode'=>'transfer','id'=>$mt,'version'=>(int)$tr->find($mt)['lock_version'],'action'=>'approve','quantities'=>[(int)$ti['id']=>'1'],'actor'=>$f['actor'],'key'=>$key()],false);

// M08 cancellation and M10 dispatch serialize on the same quote. Either ordering is valid.
$qc=$quote('1');$qd=$make($qc,'1');$act($qd,'prepare');$act($qd,'assign');$q=$qr->quote((int)$repo->quote($qc)['quote_id'],null);$before=$stock->findBalance($f['branch'],$f['variant']);$a=$worker($job($qd,'dispatch'));$b=$worker(['mode'=>'quote','id'=>(int)$q['id'],'version'=>(int)$q['lock_version'],'actor'=>$f['actor'],'key'=>$key()]);foreach([$a,$b]as $w){fwrite($w[1][0],"GO\n");fflush($w[1][0]);}$out=[$collect($a),$collect($b)];m10check(in_array('OK',$out,true),'M08 cancellation/dispatch made no progress');$q=$qr->quote((int)$q['id'],null);if($q['status']!=='cancelled')$qs->action((int)$q['id'],(int)$q['lock_version'],'cancelled',null,$f['actor'],$key(),'Finalizar cancelación concurrente');$after=$stock->findBalance($f['branch'],$f['variant']);$expectedPhysical=App\Domain\Pricing\Decimal::parse($before['physical_quantity'],6);if($repo->find($qd)['status']==='in_transit')$expectedPhysical=$expectedPhysical->subtract(App\Domain\Pricing\Decimal::parse('1',6));m10check($after['physical_quantity']===$expectedPhysical->format(6)&&$after['reserved_quantity']===App\Domain\Pricing\Decimal::parse($before['reserved_quantity'],6)->subtract(App\Domain\Pricing\Decimal::parse('1',6))->format(6),'M08 cancel versus M10 dispatch conserved balances');
// Deliberately inverted probe locks demonstrate real deadlock victim rollback in Connection.
$a=$worker(['mode'=>'deadlock','first'=>$f['branch'],'second'=>$f['other']]);$b=$worker(['mode'=>'deadlock','first'=>$f['other'],'second'=>$f['branch']]);foreach([$a,$b]as $w){fwrite($w[1][0],"GO\n");fflush($w[1][0]);}foreach([$a,$b]as $w)m10check(trim((string)fgets($w[1][1]))==='LOCKED','Deadlock barrier absent');foreach([$a,$b]as $w){fwrite($w[1][0],"NEXT\n");fflush($w[1][0]);}$deadlock=[$collect($a),$collect($b)];m10check(count(array_filter($deadlock,fn($r)=>$r==='OK'))===1&&count(array_filter($deadlock,fn($r)=>str_starts_with($r,'REJECT:')&&str_ends_with($r,':1213')))===1,'M10 real deadlock victim verified');
